import * as React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Stepper.stories";
import Stepper, { Step, StepHeader } from "./Stepper";

const { Basic } = composeStories(stories) as any;

describe("Stepper component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(<Stepper data-testid="stepper" />);
    expect(screen.getByRole("list")).toHaveAttribute("data-testid", "stepper");
  });

  it("cannot navigate to any step in linear mode", () => {
    const callback = jest.fn();
    render(
      <Stepper onStepClick={callback}>
        {Array.from(Array(4).keys()).map((idx) => (
          <Step key={idx}>
            <StepHeader>{`Step ${idx + 1}`}</StepHeader>
          </Step>
        ))}
      </Stepper>
    );
    const links = screen.getAllByRole("link");
    expect(links[0]).not.toHaveAttribute("aria-disabled");
    expect(links[1]).toHaveAttribute("aria-disabled");
    expect(links[2]).toHaveAttribute("aria-disabled");
    expect(links[3]).toHaveAttribute("aria-disabled");
    fireEvent.click(screen.getByRole("link", { name: /Step 3/ }));
    expect(callback).toHaveBeenCalledTimes(0);
  });

  it("can navigate to any step in non-linear mode", () => {
    const callback = jest.fn();
    render(
      <Stepper nonLinear onStepClick={callback}>
        {Array.from(Array(4).keys()).map((idx) => (
          <Step key={idx}>
            <StepHeader>{`Step ${idx + 1}`}</StepHeader>
          </Step>
        ))}
      </Stepper>
    );
    screen.getAllByRole("link").forEach((link) => {
      expect(link).not.toHaveAttribute("aria-disabled");
    });
    fireEvent.click(screen.getByRole("link", { name: /Step 3/ }));
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith(2);
  });
});
